_M = {"Jan": "janv.", "Feb": "févr.", "Mar": "mars", "Apr": "avr.", "May": "mai", "Jun": "juin", "Jul": "juill.", "Aug": "août", "Sep": "sept.", "Oct": "oct.", "Nov": "nov.", "Dec": "déc."}


def dates(page):
    return re.sub(r">(\s*)(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) (\d{1,2}), (\d{4})(\s*)<",
                  lambda m: ">" + m.group(1) + m.group(3) + " " + _M[m.group(2)] + " " + m.group(4) + m.group(5) + "<", page)
